  4	/**
  5	 * This class collects and provides some statistical data on the state 
  6	 * of a field. It is flexible: it will create and maintain a counter 
  7	 * for any class of object that is found within the field.
  8	 *
  9	 * @version 27.02.22
 10	 */
 11	public class FieldStats
 12	{
 13	    // Counters for each type of entity (fox, rabbit, etc.) in the simulation.
 14	    private final Map<Class<?>, Counter> counters;
 15	    // Whether the counters are currently up to date.
 16	    private boolean countsValid;
 17	    /**
 18	     * Construct a FieldStats object.
 19	     */
 20	    public FieldStats()
 21	    {
 22	        // Set up a collection for counters for each type of animal that
 23	        // we might find
 24	        counters = new HashMap<>();
 25	        countsValid = true;
 26	    }
 27	
 28	    /**
 29	     * Get details of what is in the field.
 30	     * @return A string describing what is in the field.
 31	     */
 32	    public String getPopulationDetails(Field field)
 33	    {
 34	        StringBuffer buffer = new StringBuffer();
 35	        if(!countsValid) {
 36	            generateCounts(field);
 37	        }
 38	        for(Counter info : counters.values()) {
 39	            buffer.append(info.getName());
 40	            buffer.append(": ");
 41	            buffer.append(info.getCount());
 42	            buffer.append(' ');
 43	        }
 44	        return buffer.toString();
 45	    }
 46	
 47	    /**
 48	     * Invalidate the current set of statistics; reset all 
 49	     * counts to zero.
 50	     */
 51	    public void reset()
 52	    {
 53	        countsValid = false;
 54	        for(Counter count : counters.values()) {
 55	            count.reset();
 56	        }
 57	    }
 58	
 59	    /**
 60	     * Increment the count for one class of actor.
 61	     * @param actorClass The class of actor to increment.
 62	     */
 63	    public void incrementCount(Class<?> actorClass)
 64	    {
 65	        getOrCreateCounter(actorClass).increment();
 66	    }
 67	
 68	    /**
 69	     * Indicate that an animal count has been completed.
 70	     */
 71	    public void countFinished()
 72	    {
 73	        countsValid = true;
 74	    }
 75	
 76	    /**
 77	     * Determine whether the simulation is still viable.
 78	     * I.e., should it continue to run.
 79	     * @return true If there is more than one species alive.
 80	     */
 81	    public boolean isViable(Field field)
 82	    {
 83	        // How many counts are non-zero.
 84	        int nonZero = 0;
 85	        if(!countsValid) {
 86	            generateCounts(field);
 87	        }
 88	        for(Counter info : counters.values()) {
 89	            if(info.getCount() > 0) {
 90	                nonZero++;
 91	            }
 92	        }
 93	        return nonZero > 1;
 94	    }
 95	
 96	    /**
 97	     * Generate counts of the number of actors.
 98	     * These are not kept up to date as actors
 99	     * are placed in the field, but only when a request
100	     * is made for the information.
101	     * @param field The field to generate the stats for.
102	     */
103	    private void generateCounts(Field field)
104	    {
105	        reset();
106	        for(int row = 0; row < field.getDepth(); row++) {
107	            for(int col = 0; col < field.getWidth(); col++) {
108	                Object actor = field.getObjectAt(row, col);
109	                if(actor != null) {
110	                    incrementCount(actor.getClass());
111	                }
112	                
113	            }
114	        }
115	        countsValid = true;
116	    }
117	
118	    /**
119	     * Get the counter for a class, creating it if necessary.
120	     * @param actorClass The class being counted.
121	     * @return The counter for that class.
122	     */
123	    private Counter getOrCreateCounter(Class<?> actorClass)
124	    {
125	        Counter count = counters.get(actorClass);
126	        if(count == null) {
127	            count = new Counter(actorClass.getName());
128	            counters.put(actorClass, count);
129	        }
130	        return count;
131	    }
132	}
